static void ota_popup_timer(lv_timer_t * timer)
{
    static char shownStatus[40] = "";
    bool popupHidden = lv_obj_has_flag(ui_OtaPopup, LV_OBJ_FLAG_HIDDEN);

    if(!otaInProgress()) {
        if(!popupHidden) {
            lv_obj_add_flag(ui_OtaPopup, LV_OBJ_FLAG_HIDDEN);
            lv_obj_add_flag(ui_OtaBackdrop, LV_OBJ_FLAG_HIDDEN);
            shownStatus[0] = '\0';
        }
        return;
    }

    if(popupHidden) {
        lv_obj_move_foreground(ui_OtaBackdrop);
        lv_obj_move_foreground(ui_OtaPopup);
        lv_obj_clear_flag(ui_OtaBackdrop, LV_OBJ_FLAG_HIDDEN);
        lv_obj_clear_flag(ui_OtaPopup, LV_OBJ_FLAG_HIDDEN);
    }

    // Status without the "OTA: " prefix used on the IP label.
    const char * status = otaStatusText();
    if(strncmp(status, "OTA: ", 5) == 0) status += 5;
    if(strcmp(status, shownStatus) != 0) {
        strncpy(shownStatus, status, sizeof(shownStatus) - 1);
        shownStatus[sizeof(shownStatus) - 1] = '\0';
        lv_label_set_text(ui_OtaStatusLabel, shownStatus);
    }

    // Versions: the available one is known once the check has run.
    static char shownVersions[64] = "";
    const char * available = otaAvailableVersion();
    char versions[64];
    snprintf(versions, sizeof(versions), "Installed: %s\nAvailable: %s",
             otaInstalledVersion(), available[0] ? available : "checking...");
    if(strcmp(versions, shownVersions) != 0) {
        strcpy(shownVersions, versions);
        lv_label_set_text(ui_OtaVersionLabel, shownVersions);
        lv_obj_align(ui_OtaVersionLabel, LV_ALIGN_TOP_MID, 0, 30);
    }

    // Update next to Cancel while waiting for confirmation, Cancel alone
    // otherwise.
    bool awaiting = otaAwaitingConfirm();
    if(awaiting == lv_obj_has_flag(ui_OtaConfirmButton, LV_OBJ_FLAG_HIDDEN)) {
        if(awaiting) {
            lv_label_set_text(ui_OtaConfirmLabel, otaConfirmIsReinstall() ? "Reinstall" : "Update");
            lv_obj_clear_flag(ui_OtaConfirmButton, LV_OBJ_FLAG_HIDDEN);
            lv_obj_align(ui_OtaCancelButton, LV_ALIGN_BOTTOM_RIGHT, 0, 0);
        }
        else {
            lv_obj_add_flag(ui_OtaConfirmButton, LV_OBJ_FLAG_HIDDEN);
            lv_obj_align(ui_OtaCancelButton, LV_ALIGN_BOTTOM_MID, 0, 0);
        }
    }

    int percent = otaProgress();
    if(percent >= 0) {
        lv_bar_set_value(ui_OtaBar, percent, LV_ANIM_OFF);
        lv_obj_clear_flag(ui_OtaBar, LV_OBJ_FLAG_HIDDEN);
    }
    else {
        lv_obj_add_flag(ui_OtaBar, LV_OBJ_FLAG_HIDDEN);
    }
}

static void screen_gesture_event(lv_event_t * e)
{
    if(lv_event_get_code(e) != LV_EVENT_GESTURE) return;
    // Ignore while a slide is running (the target screen is not active yet)
    // and while the colour panel is open (its slider/wheel are dragged).
    if(lv_event_get_current_target(e) != lv_scr_act()) return;
    if(!lv_obj_has_flag(ui_ColorPanel, LV_OBJ_FLAG_HIDDEN)) return;
    // No page switching while a firmware update is shown.
    if(otaInProgress()) return;

    lv_dir_t dir = lv_indev_get_gesture_dir(lv_indev_get_act());
    if(dir == LV_DIR_LEFT) switch_page(1, LV_SCR_LOAD_ANIM_MOVE_LEFT);
    else if(dir == LV_DIR_RIGHT) switch_page(-1, LV_SCR_LOAD_ANIM_MOVE_RIGHT);
    else return;
    // The swipe must not also count as a click on the button it started on.
    lv_indev_wait_release(lv_indev_get_act());
}

